// Java on virtual threads: the same guards around a blocking provider client
final class GuardedProvider {
    private final BlockingProvider delegate;
    private final Semaphore permits;
    private final Backoff backoff;

    GuardedProvider(BlockingProvider delegate, int maxConcurrent, Backoff backoff) {
        this.delegate = delegate;
        this.permits = new Semaphore(maxConcurrent);
        this.backoff = backoff;
    }

    Quote quote(String symbol) throws IOException, InterruptedException {
        if (!delegate.idempotent()) return once(symbol);             // 2. never repeat a firm quote
        for (int n = 1; ; n++) {
            try {
                return once(symbol);
            } catch (IOException e) {
                if (n > backoff.retries()) throw e;                   // out of retries
                double factor = 1 + backoff.jitter() * (ThreadLocalRandom.current().nextDouble() * 2 - 1);
                Thread.sleep((long) (backoff.nominal(n).toMillis() * factor));   // an interrupt ends it
            }
        }
    }

    private Quote once(String symbol) throws IOException, InterruptedException {
        permits.acquire();                                           // 1. every call holds a permit
        try {
            return delegate.quote(symbol);
        } finally {
            permits.release();
        }
    }
}

kotlin.src:
suspend fun <T> retrying(backoff: Backoff, random: Random, call: suspend () -> T): T {
    var n = 0
    while (true) {
        try {
            return call()
        } catch (e: IOException) {
            if (++n > backoff.retries) throw e                               // out of retries
            val factor = 1 + backoff.jitter * (random.nextDouble() * 2 - 1)  // 1 - jitter .. 1 + jitter
            delay(backoff.nominal(n) * factor)                               // so callers that failed together spread out
        }
    }
}

class GuardedProvider(
    private val delegate: Provider,
    maxConcurrent: Int,
    private val backoff: Backoff = Backoff(),
    private val hedgeAfter: Duration? = null,
    private val random: Random = Random.Default,
) : Provider {
    private val permits = Semaphore(maxConcurrent)

    override val name: String get() = delegate.name
    override val idempotent: Boolean get() = delegate.idempotent

    override suspend fun quote(symbol: String): Quote {
        val once: suspend () -> Quote = { permits.withPermit { delegate.quote(symbol) } }   // 1. every call holds a permit
        if (!delegate.idempotent) return once()                                            // 2. never repeat a firm quote
        val attempt: suspend () -> Quote = if (hedgeAfter == null) once else ({ hedged(hedgeAfter, once) })
        return retrying(backoff, random, attempt)                                          // 3. a hedge per attempt
    }
}

